--- services/range-bff/cmd/server/main.go (855 lines) ---
// Command server is the range-bff entrypoint.
//
// Mirrors services/dialogue-bff/cmd/server/main.go minus webhook wiring.
// Range v1 has no external network ingress (air-gap, spec §3.2). Loads
// config, sets up OTel tracing, builds the JWT verifier, dials range-svc
// over gRPC (mTLS when MTLS_*_FILE env vars are set), connects to NATS for
// SSE job-progress streaming, and starts an HTTP server with a chi router.
// Shutdown is graceful on SIGINT/SIGTERM.
package main

import (
	"context"
	"errors"
	"log/slog"
	"net/http"
	"net/netip"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"golang.org/x/oauth2/clientcredentials"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/eventbus"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/featureflags"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/httpserver"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/idempotency"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/migrator"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/mtls"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/observability"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/orgclient"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/vaultsecret"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/aarclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/activityclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/analysisclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/announcementclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/announcementtemplateclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/audienceclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/baselineclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/behavioralmodelclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/cascadeclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/commonsclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/config"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/credentialclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/eventclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/feedclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/frameclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/handlers"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/jobclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/jsadapter"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/kitesession"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/odintemplateclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/porchclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/rangeclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/server"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/statsclient"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/trendclient"
)

// kiteSessionTTL is the sliding participant-session lifetime; it mirrors the
// handler-side constant and bounds how long an abandoned KV entry survives.
const kiteSessionTTL = 12 * time.Hour

// svcAccountTokenSource adapts a cached client_credentials *oauth2.Token into
// the handlers.TokenSource (string, error) contract the Kite handlers consume.
type svcAccountTokenSource struct {
	tok *migrator.Token
}

func (s svcAccountTokenSource) Token(ctx context.Context) (string, error) {
	t, err := s.tok.Token(ctx)
	if err != nil {
		return "", err
	}
	return t.AccessToken, nil
}

// participantSurfacesEnabled is the fail-closed opt-in gate deciding whether
// the participant surfaces (Kite AND, since they share
// ParticipantCredentialService, Commons) are wired at all: only BOTH
// client_credentials being set enables them. A partially-configured deploy
// (one set, one missing) stays disabled rather than half-wiring a broken
// handler. Extracted as its own function so the gate is testable without a
// live NATS/gRPC stack. Named for the surfaces it gates, not for Kite alone —
// the config fields it reads keep their Kite* names because they are the
// env-var contract.
func participantSurfacesEnabled(cfg config.Config) bool {
	return cfg.KiteServiceAccountClientID != "" && cfg.KiteServiceAccountClientSecret != ""
}

// participantClientCredentials builds the *clientcredentials.Config the Kite
// and Commons surfaces both authenticate with — the SAME service-account
// credentials, since both ride range-bff's own client_credentials token
// (azp=range-bff) against the SAME participant credential (D1). Pure and
// context-free so the wiring is assertable without a live OIDC issuer.
//
// Extracting this does NOT mean the two surfaces should share a single
// *token source*: participantSvcTokenSource must still be called once per
// surface, each producing its own migrator.Token, because the cache each token
// source wraps is deliberately per-surface even though the credentials are
// shared.
func participantClientCredentials(cfg config.Config) *clientcredentials.Config {
	return &clientcredentials.Config{
		ClientID:     cfg.KiteServiceAccountClientID,
		ClientSecret: cfg.KiteServiceAccountClientSecret,
		TokenURL:     config.ServiceAccountTokenURL(cfg.OIDCIssuerURL, cfg.OIDCInternalURL),
	}
}

// participantSvcTokenSource builds a fresh svcAccountTokenSource from cfg via
// participantClientCredentials. Call it ONCE PER SURFACE (Kite, Commons)
// rather than hoisting a single shared value out of main(): the
// client_credentials are deliberately shared between the two surfaces, but
// each surface must keep its OWN independent token cache (each *migrator.Token
// wraps its own oauth2.TokenSource), so a fresh call is required per call site.
func participantSvcTokenSource(ctx context.Context, cfg config.Config) svcAccountTokenSource {
	return svcAccountTokenSource{tok: migrator.NewToken(participantClientCredentials(cfg).TokenSource(ctx))}
}

// buildKiteHandler is the single production construction seam for the
// participant KiteHandler. Extracting it out of main()'s inline
// handlers.NewKiteHandler(...) call lets a test assert the production wiring
// — in particular that WithKiteRevocationStores(commonsStore, porchStore,
// frameStore) is
// actually passed through — without standing up a live NATS connection, OIDC
// issuer, or gRPC dial (see cmd/server/main_test.go).
//
// exercises is the ExerciseService client Me/Login use to resolve the
// session's exercise avatar_style (#1900) — accepted as its own parameter
// (rather than folded into WithKiteDataClients) since it's a read-only
// display-nicety lookup, not a participant data route, and callers that don't
// need it (e.g. the revocation-only test above) can keep passing nil.
//
// porchStore (#2869) is registered alongside commonsStore for the same
// reason: Porch's porch_session login authenticates the SAME participant
// credential (ParticipantCredentialService, D1 — one login identity source
// for every synthetic-profile surface) into its own range_porch_sessions
// bucket, so a Kite credential revocation must purge it too, or a revoked
// participant lingers on Porch until that session's TTL lapses — exactly the
// gap WithKiteRevocationStores(commonsStore) was added to close for Commons.
// The store is threaded here independently of the Porch HTTP handler
// (handlers.NewPorchHandler, wired separately in main()) — kitesession.Store
// has no dependency on any particular caller, so the purge wiring stands on
// its own regardless of what else consumes porchStore.
//
// frameStore (#2872) is registered for the identical reason: Frame's
// frame_session login authenticates the SAME participant credential, so a
// revoked participant must not linger on Frame either.
func buildKiteHandler(
	cred credentialclient.ParticipantCredentialServiceClientIface,
	store kitesession.Store,
	tokens handlers.TokenSource,
	posts feedclient.PostServiceClientIface,
	chars handlers.CharacterServiceClientIface,
	exercises handlers.ExerciseServiceClientIface,
	commonsStore kitesession.Store,
	porchStore kitesession.Store,
	frameStore kitesession.Store,
	cookieSecure bool,
) *handlers.KiteHandler {
	return handlers.NewKiteHandler(cred, store, tokens,
		handlers.WithKiteDataClients(posts, chars),
		handlers.WithKiteExerciseClient(exercises),
		handlers.WithKiteRevocationStores(commonsStore, porchStore, frameStore),
		handlers.WithCookieSecure(cookieSecure))
}

// serverDepsInputs bundles every already-constructed client/handler main()
// assembles before calling server.New(). Extracted into its own type, with
// buildDeps below as its own function, purely so main()'s wiring is
// testable: a guard that server.New() attaches but is never handed a client
// (#1478) is inert — platformGate stays nil, every call site allows, and the
// feature silently does nothing in a real deployment while every test on the
// guard TYPE and on server.New() GIVEN a client stays green. main.go is the
// one call site that could forget to supply
// server.Deps.PlatformVisibilityClient, and nothing else in this repo would
// catch that omission. See TestBuildDeps_WiresPlatformVisibilityClient.
type serverDepsInputs struct {
	RangeClient        *rangeclient.Client
	FeedClient         *feedclient.Client
	EventClient        *eventclient.Client
	AudienceClient     *audienceclient.Client
	AARClient          *aarclient.Client
	StatsClient        *statsclient.Client
	ActivityClient     *activityclient.Client
	BaselineClient     *baselineclient.Client
	AnalysisClient     *analysisclient.Client
	TrendClient        *trendclient.Client
	AnnouncementClient *announcementclient.Client
	// AnnouncementTemplateClient shares RangeSvcAddr with AnnouncementClient
	// but is its own lazy-dial client package (#1527).
	AnnouncementTemplateClient *announcementtemplateclient.Client
	// OdinTemplateClient shares RangeSvcAddr with AnnouncementClient but is
	// its own lazy-dial client package (#1721/#1722).
	OdinTemplateClient *odintemplateclient.Client
	CascadeClient      *cascadeclient.Client
	JobClient          *jobclient.Client
	JobProgressH       *handlers.JobProgressHandler
	FeatureFlagCache   *featureflags.Cache
	ShareH             *handlers.ShareHandler
	OrgRoleVerifier    handlers.OrgRoleVerifier
	Verifier           *auth.JWTVerifier
	KiteHandler        *handlers.KiteHandler
	CommonsHandler     *handlers.CommonsHandler
	PorchHandler       *handlers.PorchHandler
	FrameHandler       *handlers.FrameHandler
	// BehavioralModelClient shares RangeSvcAddr with AnnouncementClient but
	// is its own lazy-dial client package (issue #1617).
	BehavioralModelClient *behavioralmodelclient.Client
	// TrustedProxyCIDRs is forwarded from cfg.TrustedProxyCIDRs to
	// server.Deps.TrustedProxyCIDRs — see security.ClientIPMiddleware.
	TrustedProxyCIDRs []netip.Prefix
	// IdemStore is forwarded to server.Deps.IdemStore (Task 6.3 pilot).
	IdemStore idempotency.Store
}

// buildDeps assembles the server.Deps main() passes to server.New() from an
// already-constructed serverDepsInputs. PlatformVisibilityClient is set from
// in.RangeClient.Exercises — the ExerciseService client is the only client
// that can resolve Exercise.platform_visibility (#1478) — so the
// platform-visibility guard server.New() builds from it is never inert in
// the real binary. in.BaselineClient and in.RangeClient are nil-checked
// because they are the two inputs this function itself DERIVES a value from
// (a handler and the ExerciseService read client respectively); every other
// client/handler field is forwarded to server.Deps as-is and server.New()
// already nil-checks each one.
func buildDeps(in serverDepsInputs) server.Deps {
	var baselineH *handlers.BaselineHandler
	if in.BaselineClient != nil {
		baselineH = handlers.NewBaselineHandler(in.BaselineClient.Baseline)
	}
	// The ExerciseService client is the only one that can resolve
	// Exercise.platform_visibility. nil is safe — server.New() /
	// handlers.NewPlatformGuard both treat a nil client as "no guard".
	var pvClient handlers.ExerciseServiceClientIface
	if in.RangeClient != nil {
		pvClient = in.RangeClient.Exercises
	}
	return server.Deps{
		MetricsHandler:             observability.MetricsHandler(),
		MetricsMiddleware:          observability.HTTPMetricsMiddleware(),
		KiteH:                      in.KiteHandler,
		CommonsH:                   in.CommonsHandler,
		PorchH:                     in.PorchHandler,
		FrameH:                     in.FrameHandler,
		Verifier:                   in.Verifier,
		RangeClient:                in.RangeClient,
		RangeTypedClient:           in.RangeClient,
		FeedClient:                 in.FeedClient,
		EventClient:                in.EventClient,
		AudienceClient:             in.AudienceClient,
		AARClient:                  in.AARClient,
		StatsClient:                in.StatsClient,
		ActivityClient:             in.ActivityClient,
		BaselineH:                  baselineH,
		AnalysisClient:             in.AnalysisClient,
		TrendClient:                in.TrendClient,
		AnnouncementClient:         in.AnnouncementClient,
		AnnouncementTemplateClient: in.AnnouncementTemplateClient,
		OdinTemplateClient:         in.OdinTemplateClient,
		BehavioralModelClient:      in.BehavioralModelClient,
		CascadeClient:              in.CascadeClient,
		JobClient:                  in.JobClient,
		JobProgressH:               in.JobProgressH,
		FeatureFlagCache:           in.FeatureFlagCache,
		ShareH:                     in.ShareH,
		OrgRoleVerifier:            in.OrgRoleVerifier,
		// #1478 — the platform-visibility guard's ONLY source. If this line
		// is ever removed or set to nil, TestBuildDeps_WiresPlatformVisibilityClient
		// fails; nothing else would.
		PlatformVisibilityClient: pvClient,
		TrustedProxyCIDRs:        in.TrustedProxyCIDRs,
		IdemStore:                in.IdemStore,
	}
}

// errPlatformVisibilityClientNil is returned by requirePlatformVisibilityClient
// when deps.PlatformVisibilityClient is nil.
var errPlatformVisibilityClientNil = errors.New(
	"server.Deps.PlatformVisibilityClient is nil — the platform-visibility guard " +
		"(#1478) would be handlers.NewPlatformGuard(nil, ...), which returns a nil " +
		"*platformGuard, and every guard call site treats nil as ALWAYS ALLOW; " +
		"every platform-visibility gate in this service would silently become a " +
		"no-op with no error, no log line, and no failing test")

// requirePlatformVisibilityClient is main()'s boot-time gate against exactly
// that silent-failure class (TASK 9): buildDeps derives PlatformVisibilityClient
// from RangeClient.Exercises, and in production RangeClient is guaranteed
// non-nil (main() os.Exit(1)s a few lines above if rangeclient.Dial fails) —
// so a nil PlatformVisibilityClient reaching this call can only mean a wiring
// regression in buildDeps or in main()'s serverDepsInputs literal, not a
// legitimate "feature not configured" state (unlike, say, ffCache/OrgSvcAddr,
// which are genuinely optional). main() calls this immediately after
// buildDeps and before server.New(deps); a non-nil error means the process
// refuses to start rather than silently serving traffic with every
// platform-visibility gate wide open.
func requirePlatformVisibilityClient(deps server.Deps) error {
	if deps.PlatformVisibilityClient == nil {
		return errPlatformVisibilityClientNil
	}
	return nil
}

func main() {
	logger := observability.NewLogger(os.Stdout, slog.LevelInfo)

	cfg, err := config.Load()
	if err != nil {
		logger.Error("config.Load", "err", err)
		os.Exit(1)
	}

	rootCtx, cancel := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer cancel()

	// Shared HMAC key auth.ForwardingContext/bearerCtx mint x-tenant-assertion
	// with — the same key ws-gateway's SharedSubscriber verifies against.
	// Vault (VAULT_ADDR + VAULT_TOKEN) takes precedence; NATS_TENANT_ASSERTION_KEY
	// is the smoke-stack/dev-mode fallback. Unlike ws-gateway, a load failure
	// here is NOT fatal — this BFF has no other use for the key, so failing to
	// boot over it would be strictly worse than omitting x-tenant-assertion.
	auth.TenantAssertionSigningKey = vaultsecret.LoadTenantAssertionKeyTolerant(
		rootCtx, logger, cfg.VaultAddr, cfg.VaultToken, cfg.VaultTenantAssertionKVMount, cfg.NATSTenantAssertionKey,
	)

	// OTel tracer — optional; skipped when OTLP_ENDPOINT is unset.
	if cfg.OTLPEndpoint != "" {
		var tracerOpts []observability.TracerOption
		if cfg.OTLPInsecure {
			tracerOpts = append(tracerOpts, observability.WithOTLPInsecure())
		}
		tracerShutdown, err := observability.SetupTracer(rootCtx, cfg.ServiceName, cfg.OTLPEndpoint, tracerOpts...)
		if err != nil {
			logger.Error("observability.SetupTracer", "err", err)
			os.Exit(1)
		}
		defer func() { _ = tracerShutdown(context.Background()) }()
	}

	// Prometheus metrics — direct scrape (Path B, spec §3).
	meterShutdown, err := observability.SetupMeter(rootCtx, cfg.ServiceName, cfg.Version)
	if err != nil {
		logger.Error("observability.SetupMeter", "err", err)
		os.Exit(1)
	}
	defer func() { _ = meterShutdown(context.Background()) }()

	// JWT verifier — validates bearer tokens against the OIDC JWKS endpoint.
	verifier, err := auth.NewJWTVerifier(rootCtx, cfg.OIDCIssuerURL, cfg.OIDCInternalURL, cfg.OIDCAudience)
	if err != nil {
		logger.Error("auth.NewJWTVerifier", "err", err)
		os.Exit(1)
	}

	// East-west mTLS posture. When MTLS_*_FILE env vars are set the gRPC
	// dial uses mTLS; when unset it falls back to insecure transport.
	// Partial configuration is a hard error (caught by config.Load above).
	mtlsCfg := mtls.Config{
		CertFile: cfg.MTLSCertFile,
		KeyFile:  cfg.MTLSKeyFile,
		CAFile:   cfg.MTLSCAFile,
	}
	rClient, err := rangeclient.Dial(cfg.RangeSvcAddr, mtlsCfg)
	if err != nil {
		logger.Error("rangeclient.Dial", "err", err)
		os.Exit(1)
	}
	defer func() { _ = rClient.Close() }()

	// feedclient shares the same downstream address as rangeclient — it
	// connects to the same range-svc gRPC server via a second ClientConn.
	// A single ClientConn supporting both would require merging the two packages;
	// the lazy-dial approach means no handshake happens until the first RPC.
	fClient, err := feedclient.New(cfg.RangeSvcAddr, mtlsCfg)
	if err != nil {
		logger.Error("feedclient.New", "err", err)
		os.Exit(1)
	}
	defer func() { _ = fClient.Close() }()

	// eventclient shares the same downstream address — lazy dial, separate
	// ClientConn so the package boundary is clean (mirrors feedclient rationale).
	eClient, err := eventclient.New(cfg.RangeSvcAddr, mtlsCfg)
	if err != nil {
		logger.Error("eventclient.New", "err", err)
		os.Exit(1)
	}
	defer func() { _ = eClient.Close() }()

	// audienceclient shares the same downstream address — lazy dial, separate
	// ClientConn so the package boundary is clean (mirrors eventclient rationale).
	aClient, err := audienceclient.New(cfg.RangeSvcAddr, mtlsCfg)
	if err != nil {
		logger.Error("audienceclient.New", "err", err)
		os.Exit(1)
	}
	defer func() { _ = aClient.Close() }()

	// aarclient shares the same downstream address — lazy dial, separate
	// ClientConn so the package boundary is clean (mirrors audienceclient rationale).
	aarClient, err := aarclient.New(cfg.RangeSvcAddr, mtlsCfg)
	if err != nil {
		logger.Error("aarclient.New", "err", err)
		os.Exit(1)
	}
	defer func() { _ = aarClient.Close() }()

	// statsclient shares the same downstream address — lazy dial, separate
	// ClientConn so the package boundary is clean (mirrors aarclient rationale).
	statsClient, err := statsclient.New(cfg.RangeSvcAddr, mtlsCfg)
	if err != nil {
		logger.Error("statsclient.New", "err", err)
		os.Exit(1)
	}
	defer func() { _ = statsClient.Close() }()

	// activityclient shares the same downstream address — lazy dial, separate
	// ClientConn so the package boundary is clean (mirrors statsclient rationale).
	// Backs the recent-activity feed (issue #484).
	activityClient, err := activityclient.New(cfg.RangeSvcAddr, mtlsCfg)
	if err != nil {
		logger.Error("activityclient.New", "err", err)
		os.Exit(1)
	}
	defer func() { _ = activityClient.Close() }()

	// baselineclient shares the same downstream address — lazy dial, separate
	// ClientConn so the package boundary is clean (mirrors statsclient rationale).
	baselineClient, err := baselineclient.New(cfg.RangeSvcAddr, mtlsCfg)
	if err != nil {
		logger.Error("baselineclient.New", "err", err)
		os.Exit(1)
	}
	defer func() { _ = baselineClient.Close() }()

	// org-svc gRPC client — OPTIONAL. Dialed with the SAME mTLS posture as
	// range-svc. Needed by the feature-flag gate (RequireVerticalEnabled) and
	// by the cross-org enroll-by-code flow (#332): when ORG_SVC_ADDR is unset
	// the flag cache is nil (gate is a no-op pass-through, fail-safe-open for
	// local dev) and the enrollment routes stay unregistered (there is no
	// org-svc peer to redeem a pasted share code against). Mirrors dialogue-bff's
	// optional org-svc dial.
	var ffCache *featureflags.Cache
	// shareH is only built when org-svc is available — Enroll requires the
	// org-svc code redeemer alongside the range-svc EnrollmentService client
	// (enroll-by-code redesign, #332). When oClient is nil, shareH stays nil and
	// the enrollment routes are not registered.
	var shareH *handlers.ShareHandler
	// orgRoleVerifier resolves the caller's org-membership role via org-svc
	// VerifyMembership so ResolveOrgRole can forward x-org-role on the
	// access-management routes (#332b Decision A). Only wired when org-svc is
	// available; nil otherwise (the middleware degrades to a pass-through no-op).
	var orgRoleVerifier handlers.OrgRoleVerifier
	if cfg.OrgSvcAddr != "" {
		oClient, oErr := orgclient.NewClient(cfg.OrgSvcAddr, mtlsCfg)
		if oErr != nil {
			logger.Error("orgclient.NewClient", "err", oErr)
			os.Exit(1)
		}
		defer func() { _ = oClient.Close() }()
		logger.InfoContext(rootCtx, "org-svc client transport", "mtls_mode", oClient.Mode.String())
		ffCache = featureflags.NewCache(func(ctx context.Context) (map[string]bool, error) {
			return oClient.ListFeatureFlags(ctx)
		}, 15*time.Second, logger)
		shareH = handlers.NewShareHandler(rClient.Enrollment, oClient)
		orgRoleVerifier = oClient
	} else {
		logger.WarnContext(rootCtx, "ORG_SVC_ADDR not set; range vertical feature-flag gate is disabled (fail-safe-open), and the cross-org enroll-by-code flow (/api/v1/range/exercises/{id}/shares) is unavailable")
	}

	// analysisclient shares the same downstream address — lazy dial, separate
	// ClientConn so the package boundary is clean (mirrors statsclient rationale).
	analysisClient, err := analysisclient.New(cfg.RangeSvcAddr, mtlsCfg)
	if err != nil {
		logger.Error("analysisclient.New", "err", err)
		os.Exit(1)
	}
	defer func() { _ = analysisClient.Close() }()

	// trendclient shares the same downstream address — lazy dial, separate
	// ClientConn so the package boundary is clean (mirrors statsclient rationale).
	trendClient, err := trendclient.New(cfg.RangeSvcAddr, mtlsCfg)
	if err != nil {
		logger.Error("trendclient.New", "err", err)
		os.Exit(1)
	}
	defer func() { _ = trendClient.Close() }()

	// announcementclient shares the same downstream address — lazy dial, separate
	// ClientConn so the package boundary is clean (mirrors analysisclient rationale).
	announcementClient, err := announcementclient.New(cfg.RangeSvcAddr, mtlsCfg)
	if err != nil {
		logger.Error("announcementclient.New", "err", err)
		os.Exit(1)
	}
	defer func() { _ = announcementClient.Close() }()

	// announcementtemplateclient shares the same downstream address — lazy
	// dial, separate ClientConn so the package boundary is clean (mirrors
	// announcementclient rationale). Mandatory, not opt-in: unlike org-svc,
	// there is no new downstream service here, so a dial failure exits like
	// every other range-svc-backed client.
	announcementTemplateClient, err := announcementtemplateclient.New(cfg.RangeSvcAddr, mtlsCfg)
	if err != nil {
		logger.Error("announcementtemplateclient.New", "err", err)
		os.Exit(1)
	}
	defer func() { _ = announcementTemplateClient.Close() }()

	// odintemplateclient shares the same downstream address — lazy dial,
