			handlers.WithCommonsCookieSecure(cfg.CookieSecure))

		// Porch surface — its OWN credential dial and OWN token cache (each
		// surface must keep an independent token cache; see
		// participantSvcTokenSource). Do not reuse Kite's or Commons's
		// credClient/tokenSrc here (D2).
		porchCredClient, err := credentialclient.New(cfg.RangeSvcAddr, mtlsCfg)
		if err != nil {
			logger.Error("credentialclient.New (porch)", "err", err)
			os.Exit(1)
		}
		defer func() { _ = porchCredClient.Close() }()

		porchTokenSrc := participantSvcTokenSource(rootCtx, cfg)

		porchHandler = handlers.NewPorchHandler(
			porchCredClient.Credentials, porchClient.Porch, porchStore, porchTokenSrc,
			handlers.WithPorchCharacterClient(rClient.Characters),
			handlers.WithPorchCookieSecure(cfg.CookieSecure))

		// Frame surface — its OWN credential dial and OWN token cache (each
		// surface must keep an independent token cache; see
		// participantSvcTokenSource). Do not reuse Kite's, Commons's or
		// Porch's credClient/tokenSrc here (D2).
		frameCredClient, err := credentialclient.New(cfg.RangeSvcAddr, mtlsCfg)
		if err != nil {
			logger.Error("credentialclient.New (frame)", "err", err)
			os.Exit(1)
		}
		defer func() { _ = frameCredClient.Close() }()

		frameTokenSrc := participantSvcTokenSource(rootCtx, cfg)

		frameHandler = handlers.NewFrameHandler(
			frameCredClient.Credentials, frameClient.Videos, frameStore, frameTokenSrc,
			handlers.WithFrameCharacterClient(rClient.Characters),
			handlers.WithFrameCookieSecure(cfg.CookieSecure))
	}

	deps := buildDeps(serverDepsInputs{
		RangeClient:                rClient,
		FeedClient:                 fClient,
		EventClient:                eClient,
		AudienceClient:             aClient,
		AARClient:                  aarClient,
		StatsClient:                statsClient,
		ActivityClient:             activityClient,
		BaselineClient:             baselineClient,
		AnalysisClient:             analysisClient,
		TrendClient:                trendClient,
		AnnouncementClient:         announcementClient,
		AnnouncementTemplateClient: announcementTemplateClient,
		OdinTemplateClient:         odinTemplateClient,
		BehavioralModelClient:      behavioralModelClient,
		CascadeClient:              cascadeClient,
		JobClient:                  jobClient,
		JobProgressH:               jobProgressH,
		FeatureFlagCache:           ffCache,
		// ShareH is only non-nil when ORG_SVC_ADDR is set (Create needs the
		// org-svc share-code redeemer, redeem flow #332); otherwise nil and the
		// share routes stay unregistered.
		ShareH:            shareH,
		OrgRoleVerifier:   orgRoleVerifier,
		Verifier:          verifier,
		KiteHandler:       kiteHandler,
		CommonsHandler:    commonsHandler,
		PorchHandler:      porchHandler,
		FrameHandler:      frameHandler,
		TrustedProxyCIDRs: cfg.TrustedProxyCIDRs,
		IdemStore:         idemStore,
	})

	// TASK 9 boot-time gate (#1478 nil-wiring class): refuse to start rather
	// than silently serve traffic with every platform-visibility gate
	// wide-open. See requirePlatformVisibilityClient's doc comment.
	if err := requirePlatformVisibilityClient(deps); err != nil {
		logger.Error("platform visibility wiring", "err", err)
		os.Exit(1)
	}

	handler := server.New(deps)

	srv := httpserver.Server(cfg.HTTPAddr, handler)

	// Graceful shutdown on SIGINT/SIGTERM.
	go func() {
		<-rootCtx.Done()
		shutCtx, shutCancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer shutCancel()
		_ = srv.Shutdown(shutCtx)
	}()

	logger.InfoContext(rootCtx, "range-bff starting", "addr", cfg.HTTPAddr)
	if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
		logger.Error("ListenAndServe", "err", err)
		os.Exit(1)
	}
}


