		if err != nil {
			logger.Error("jetstream.New", "err", err)
			os.Exit(1)
		}
		kiteStore, err := kitesession.NewNATSStore(rootCtx, js2, kiteSessionTTL)
		if err != nil {
			logger.Error("kitesession.NewNATSStore", "err", err)
