		// surface must keep an independent token cache; see participantSvcTokenSource).
		commonsCredClient, err := credentialclient.New(cfg.RangeSvcAddr, mtlsCfg)
		if err != nil {
			logger.Error("credentialclient.New (commons)", "err", err)
			os.Exit(1)
