func TestKiteRevocationStores_WiredFromMain(t *testing.T) {
	ctx := context.Background()
	kiteStore := kitesession.NewMemStore()
	commonsStore := kitesession.NewMemStore()
	porchStore := kitesession.NewMemStore()
	frameStore := kitesession.NewMemStore()
	require.NoError(t, kiteStore.Put(ctx, kitesession.Session{Token: "kite-tok", CharacterID: "char-9"}, time.Hour))
	require.NoError(t, commonsStore.Put(ctx, kitesession.Session{Token: "reddit-tok", CharacterID: "char-9"}, time.Hour))
	// An unrelated character's Reddit session must survive.
	require.NoError(t, commonsStore.Put(ctx, kitesession.Session{Token: "reddit-other", CharacterID: "char-other"}, time.Hour))
	require.NoError(t, porchStore.Put(ctx, kitesession.Session{Token: "porch-tok", CharacterID: "char-9"}, time.Hour))
	// An unrelated character's Porch session must survive.
	require.NoError(t, porchStore.Put(ctx, kitesession.Session{Token: "porch-other", CharacterID: "char-other"}, time.Hour))
	require.NoError(t, frameStore.Put(ctx, kitesession.Session{Token: "frame-tok", CharacterID: "char-9"}, time.Hour))
	// An unrelated character's Frame session must survive.
	require.NoError(t, frameStore.Put(ctx, kitesession.Session{Token: "frame-other", CharacterID: "char-other"}, time.Hour))

	cred := &fakeRevokeCredClient{
		revokeFn: func(_ context.Context, _ *credentialv1.RevokeCredentialRequest, _ ...grpc.CallOption) (*credentialv1.RevokeCredentialResponse, error) {
			return &credentialv1.RevokeCredentialResponse{
				Credential: &credentialv1.ParticipantCredential{Handle: "agent_smith", IsActive: false},
			}, nil
		},
	}

	// buildKiteHandler is the production wiring seam (see file doc above) —
	// NOT a test-built handler like handlers_test's own cross-purge test uses.
	h := buildKiteHandler(cred, kiteStore, fakeMainTokenSource("svc-jwt"), nil, nil, nil, commonsStore, porchStore, frameStore, true)

	r := chi.NewRouter()
	r.Post("/api/v1/kite/exercises/{id}/credentials:revoke", h.RevokeCredential)
	req := httptest.NewRequest(http.MethodPost, "/api/v1/kite/exercises/ex-1/credentials:revoke",
		strings.NewReader(`{"character_id":"char-9"}`))
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Authorization", "Bearer instructor-jwt")
	rec := httptest.NewRecorder()
	r.ServeHTTP(rec, req)

	require.Equal(t, http.StatusOK, rec.Code, rec.Body.String())

	if _, err := kiteStore.Get(ctx, "kite-tok"); err == nil {
		t.Error("char-9's Kite session must be purged")
	}
	if _, err := commonsStore.Get(ctx, "reddit-tok"); err == nil {
		t.Error("char-9's Reddit session must ALSO be purged — proves main.go's " +
			"buildKiteHandler call actually wires WithKiteRevocationStores(commonsStore)")
	}
	if _, err := commonsStore.Get(ctx, "reddit-other"); err != nil {
		t.Error("an unrelated character's Reddit session must survive the revoke")
	}
	if _, err := porchStore.Get(ctx, "porch-tok"); err == nil {
		t.Error("char-9's Porch session must ALSO be purged (#2869) — proves main.go's " +
			"buildKiteHandler call actually wires WithKiteRevocationStores(..., porchStore)")
	}
	if _, err := porchStore.Get(ctx, "porch-other"); err != nil {
		t.Error("an unrelated character's Porch session must survive the revoke")
	}
	if _, err := frameStore.Get(ctx, "frame-tok"); err == nil {
		t.Error("char-9's Frame session must ALSO be purged (#2872) — proves main.go's " +
			"buildKiteHandler call actually wires WithKiteRevocationStores(..., frameStore)")
	}
	if _, err := frameStore.Get(ctx, "frame-other"); err != nil {
		t.Error("an unrelated character's Frame session must survive the revoke")
	}
}

// TestKiteClientCredentials pins the *clientcredentials.Config that the Kite
