			}
			cc := participantClientCredentials(cfg)
			require.Equal(t, "kite-client", cc.ClientID)
			require.Equal(t, "kite-secret", cc.ClientSecret)
			require.Equal(t, config.ServiceAccountTokenURL(tc.issuerURL, tc.internalURL), cc.TokenURL)
		})
	}
}

