// TestRequirePlatformVisibilityClient pins TASK 9's boot-time gate against the
// nil-wiring class of bug: handlers.NewPlatformGuard silently returns nil
// when handed a nil client, and a nil *platformGuard ALWAYS allows (see
// internal/handlers/platform_visibility.go's package doc). Before this
// change, a serverDepsInputs literal that forgot to thread RangeClient (or a
// buildDeps edit that dropped the PlatformVisibilityClient line) produced a
// server.Deps that booted and served traffic exactly as if #1478 had never
// shipped — no error, no log, no failing test anywhere in the suite.
//
// requirePlatformVisibilityClient is the seam main() calls, right before
// server.New(deps), with the SAME server.Deps buildDeps produced — not a
// hand-built stand-in — so a regression in either buildDeps or main()'s own
// serverDepsInputs literal surfaces here.
func TestRequirePlatformVisibilityClient(t *testing.T) {
	t.Run("PlatformVisibilityClient nil — refuses to start", func(t *testing.T) {
		// buildDeps(serverDepsInputs{}) is exactly what a RangeClient-less
		// wiring regression produces in production (main.go os.Exit(1)s before
		// this point if the real range-svc dial fails, so RangeClient is never
		// nil in practice — this reproduces a dropped-field regression, not a
		// reachable runtime state).
		deps := buildDeps(serverDepsInputs{})
		err := requirePlatformVisibilityClient(deps)
		require.Error(t, err,
			"a nil PlatformVisibilityClient must fail closed at boot — the alternative is every "+
				"platform-visibility gate silently allowing everything in production (#1478)")
	})

	t.Run("PlatformVisibilityClient wired — boots normally", func(t *testing.T) {
		rc := &rangeclient.Client{Exercises: exercisev1.NewExerciseServiceClient(nil)}
		deps := buildDeps(serverDepsInputs{RangeClient: rc})
		require.NoError(t, requirePlatformVisibilityClient(deps))
	})
}


