package main

// main_wiring_test.go pins the cross-platform credential-revocation wiring
// inside main() (issue #1885 AC — "Cross-platform revocation still works,
// with a test"; ticket note "Preserve the cross-platform revocation coupling
// — Kite/X credential revocation purges Commons sessions").
//
// FALSE-PASS VERIFIED: TestKiteRevokeCredential_AlsoPurgesAdditionalStores
// (internal/handlers/kite_credential_test.go) proves WithKiteRevocationStores(...)
// purges an injected store when the caller wires it — but it builds
// handlers.NewKiteHandler directly with a hand-rolled kitesession.NewMemStore() and
// never touches this file. It CANNOT catch main.go dropping the option from
// its OWN handlers.NewKiteHandler(...) call, which is exactly what this ticket's
// AC is about.
//
// main() itself dials real NATS/mTLS/OIDC infra and calls os.Exit on error,
// so it cannot be safely invoked from a unit test — there is no exported
// seam that separates "build the option list" from "make the network calls".
// This test instead parses main.go's OWN source (this package's file) and
// asserts, via go/ast, that its handlers.NewKiteHandler(...) call site includes
// a WithKiteRevocationStores(...) argument. This is deliberately naming-agnostic
// (it does not care whether the store variable is called redditStore or
// commonsStore) so it survives the #1885 rename unmodified and keeps
// pinning the ONE thing that actually regresses: the option being dropped
// from the call.
import (
	"go/ast"
	"go/parser"
	"go/token"
	"testing"
)

func TestMainWiring_KiteHandlerIncludesRevocationStoresOption(t *testing.T) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "main.go", nil, 0)
	if err != nil {
		t.Fatalf("parse main.go: %v", err)
	}

	newKiteHandlerCallFound := false
	hasRevocationOption := false

	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok || sel.Sel.Name != "NewKiteHandler" {
			return true
		}
		newKiteHandlerCallFound = true
		for _, arg := range call.Args {
			argCall, ok := arg.(*ast.CallExpr)
			if !ok {
				continue
			}
			argSel, ok := argCall.Fun.(*ast.SelectorExpr)
			if ok && argSel.Sel.Name == "WithKiteRevocationStores" {
				hasRevocationOption = true
			}
		}
		return true
	})

	if !newKiteHandlerCallFound {
		t.Fatal("handlers.NewKiteHandler(...) call not found in main.go — has the wiring moved?")
	}
	if !hasRevocationOption {
		t.Error("main.go's handlers.NewKiteHandler(...) call is missing a WithKiteRevocationStores(...) " +
			"option — an X/Kite credential revoke will no longer purge live Commons participant sessions")
	}
}

// TestMainWiring_PorchHandlerConstructedAndThreadedIntoDeps pins the exact
// defect a code review caught: handlers.NewPorchHandler and porchclient.New
// both existed on this branch (fully unit-tested in their own packages), and
// serverDepsInputs/buildDeps both had every plumbing hook needed, but main()
// itself never called handlers.NewPorchHandler(...) and never set the
// PorchHandler field in its serverDepsInputs{...} literal — so
// deps.PorchH was always nil in the real built binary and every
// /api/v1/porch/* route 404'd (server.go registers them all behind
// `if deps.PorchH != nil`), even though porch_routes_test.go was green: that
// file builds Deps by hand via a newDepsWithPorch() test-only helper and
// never touches main()'s construction path at all.
//
// Like TestMainWiring_KiteHandlerIncludesRevocationStoresOption above, main()
// dials real NATS/mTLS/OIDC infra and os.Exit(1)s on failure, so it cannot be
// safely invoked from a unit test — there is no seam that separates "build
// the dependency graph" from "make the network calls". This test instead
// parses main.go's OWN source via go/ast and asserts both halves of the
// wiring:
//
//  1. a handlers.NewPorchHandler(...) call exists at all, and
//  2. some serverDepsInputs{...} composite literal in this file sets a
//     PorchHandler: field to something other than a literal nil.
//
// Either half regressing again — the constructor call disappearing, or its
// result silently failing to reach the struct literal — reproduces exactly
// the shipped defect and fails this test red.
func TestMainWiring_PorchHandlerConstructedAndThreadedIntoDeps(t *testing.T) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "main.go", nil, 0)
	if err != nil {
		t.Fatalf("parse main.go: %v", err)
	}

	newPorchHandlerCallFound := false
	porchHandlerFieldWired := false

	ast.Inspect(file, func(n ast.Node) bool {
		if call, ok := n.(*ast.CallExpr); ok {
			if sel, ok := call.Fun.(*ast.SelectorExpr); ok && sel.Sel.Name == "NewPorchHandler" {
				newPorchHandlerCallFound = true
			}
		}

		lit, ok := n.(*ast.CompositeLit)
		if !ok {
			return true
		}
		ident, ok := lit.Type.(*ast.Ident)
		if !ok || ident.Name != "serverDepsInputs" {
			return true
		}
		for _, elt := range lit.Elts {
			kv, ok := elt.(*ast.KeyValueExpr)
			if !ok {
				continue
			}
			key, ok := kv.Key.(*ast.Ident)
			if !ok || key.Name != "PorchHandler" {
				continue
			}
			if valueIdent, ok := kv.Value.(*ast.Ident); ok && valueIdent.Name == "nil" {
				continue
			}
			porchHandlerFieldWired = true
		}
		return true
	})

	if !newPorchHandlerCallFound {
		t.Fatal("handlers.NewPorchHandler(...) call not found in main.go — Porch's HTTP handler " +
			"(login/logout/me/feed/post routes) is never constructed, so server.go's " +
			"`if deps.PorchH != nil` guard leaves the entire /api/v1/porch/* surface unregistered " +
			"(404) in the real built binary")
	}
	if !porchHandlerFieldWired {
		t.Error("no serverDepsInputs{...} literal in main.go sets PorchHandler to a non-nil value — " +
			"handlers.NewPorchHandler's result must reach buildDeps via serverDepsInputs.PorchHandler " +
			"for server.Deps.PorchH (and therefore every porch route) to be wired in production")
	}
}



